sealed interface Expr permits Nombre, Addition, Multiplication { }
record Nombre(double valeur) implements Expr { }
record Addition(Expr gauche, Expr droite) implements Expr { }
record Multiplication(Expr gauche, Expr droite) implements Expr { }

static double evaluer(Expr e) {
    // Ecris ici un switch exhaustif et recursif, sans default
}

solution:
static double evaluer(Expr e) {
    return switch (e) {
        case Nombre(double v) -> v;
        case Addition(Expr g, Expr d) -> evaluer(g) + evaluer(d);
        case Multiplication(Expr g, Expr d) -> evaluer(g) * evaluer(d);
    };
}
